    @inline(__always)
    private func checkSlideDownLanesConstantA(_ value: Lane) {
        let mismatches = Mismatches("slideDownLanes with a repeating \(hex(value))")
        let lanesInputs = Inputs.laneAmounts(lanes: H.laneCount, inContract: true)
        mismatches.check(
            H.repeating(value),
            H(raw: HighwayReference.repeatingI64(value)),
            "repeating"
        )
        for lanes in lanesInputs {
            mismatches.check(
                H.slideDownLanes(H.repeating(value), by: lanes),
                H(raw: HighwayReference.slideDownLanesI64(H.repeating(value).raw, lanes)),
                "lanes: \(lanes)"
            )
        }
        mismatches.record()
    }

